100: - name: (Deprecation) Catch and report renamed settings in matrix_synapse_configuration_extension_yaml
101:   ansible.builtin.fail:
102:     msg: >-
103:       Your matrix_synapse_configuration_extension_yaml configuration contains a variable, which now has a different name.
104:       Please rename the variable (`{{ item.old }}` -> `{{ item.new }}`) on your configuration file (vars.yml).
105:   when: "item.old in matrix_synapse_configuration_extension"
106:   with_items:
107:     - {'old': 'federation_ip_range_blacklist', 'new': 'ip_range_blacklist'}
108: 
109: - name: Fail if required Synapse settings not defined
110:   ansible.builtin.fail:
111:     msg: >-
112:       You need to define a required configuration setting (`{{ item.name }}`).
113:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
114:   with_items:
115:     - {'name': 'matrix_synapse_username', when: true}
116:     - {'name': 'matrix_synapse_uid', when: true}
117:     - {'name': 'matrix_synapse_gid', when: true}
118:     - {'name': 'matrix_synapse_container_network', when: true}
119:     - {'name': 'matrix_synapse_macaroon_secret_key', when: true}
120:     - {'name': 'matrix_synapse_database_host', when: true}
121:     - {'name': 'matrix_synapse_database_user', when: true}
122:     - {'name': 'matrix_synapse_database_password', when: true}
123:     - {'name': 'matrix_synapse_database_database', when: true}
124: 
125:     - {'name': 'matrix_synapse_container_labels_public_client_root_traefik_hostname', when: "{{ matrix_synapse_container_labels_public_client_root_enabled }}"}
126:     - {'name': 'matrix_synapse_container_labels_public_client_root_redirection_url', when: "{{ matrix_synapse_container_labels_public_client_root_redirection_enabled }}"}
127: 
128:     - {'name': 'matrix_synapse_container_labels_public_client_api_traefik_hostname', when: "{{ matrix_synapse_container_labels_public_client_api_enabled }}"}
129: 
130:     - {'name': 'matrix_synapse_container_labels_internal_client_api_traefik_entrypoints', when: "{{ matrix_synapse_container_labels_internal_client_api_enabled }}"}
131:     - {'name': 'matrix_synapse_container_labels_internal_client_synapse_admin_api_traefik_entrypoints', when: "{{ matrix_synapse_container_labels_internal_client_synapse_admin_api_enabled }}"}
132: 
133:     - {'name': 'matrix_synapse_container_labels_public_client_synapse_client_api_traefik_hostname', when: "{{ matrix_synapse_container_labels_public_client_synapse_client_api_enabled }}"}
134:     - {'name': 'matrix_synapse_container_labels_public_client_synapse_admin_api_traefik_hostname', when: "{{ matrix_synapse_container_labels_public_client_synapse_admin_api_enabled }}"}
135: 
136:     - {'name': 'matrix_synapse_container_labels_public_federation_api_traefik_hostname', when: "{{ matrix_synapse_container_labels_public_federation_api_enabled }}"}
137:     - {'name': 'matrix_synapse_container_labels_public_federation_api_traefik_entrypoints', when: "{{ matrix_synapse_container_labels_public_federation_api_enabled }}"}
138: 
139:     - {'name': 'matrix_synapse_metrics_proxying_hostname', when: "{{ matrix_synapse_metrics_proxying_enabled }}"}
140:     - {'name': 'matrix_synapse_metrics_proxying_path_prefix', when: "{{ matrix_synapse_metrics_proxying_enabled }}"}
141: 
142:     - {'name': 'matrix_synapse_matrix_authentication_service_endpoint', when: "{{ matrix_synapse_matrix_authentication_service_enabled }}"}
143:     - {'name': 'matrix_synapse_matrix_authentication_service_secret', when: "{{ matrix_synapse_matrix_authentication_service_enabled }}"}
144: 
145:     - {'name': 'matrix_synapse_container_labels_traefik_compression_middleware_name', when: "{{ matrix_synapse_container_labels_traefik_compression_middleware_enabled }}"}
