147: - name: Fail if asking for more than 1 instance of single-instance workers
148:   ansible.builtin.fail:
149:     msg: >-
150:       `{{ item }}` cannot be more than 1. This is a single-instance worker.
151:   when: "lookup('vars', item, default='') | int > 1"
152:   with_items:
153:     - "matrix_synapse_workers_appservice_workers_count"
154:     - "matrix_synapse_workers_user_dir_workers_count"
155:     - "matrix_synapse_workers_background_workers_count"
156:     - "matrix_synapse_workers_stream_writer_typing_stream_workers_count"
157:     - "matrix_synapse_workers_stream_writer_to_device_stream_workers_count"
158:     - "matrix_synapse_workers_stream_writer_account_data_stream_workers_count"
159:     - "matrix_synapse_workers_stream_writer_receipts_stream_workers_count"
160:     - "matrix_synapse_workers_stream_writer_presence_stream_workers_count"
161:     - "matrix_synapse_workers_stream_writer_push_rules_stream_workers_count"
162: 
163: - name: Fail if matrix-synapse-reverse-proxy-companion access log format is invalid
164:   ansible.builtin.fail:
165:     msg: >-
166:       `matrix_synapse_reverse_proxy_companion_access_log_format` must be one of:
167:       {{ matrix_synapse_reverse_proxy_companion_access_log_format_presets.keys() | sort | join(', ') }}
168:   when: "matrix_synapse_reverse_proxy_companion_access_log_format not in matrix_synapse_reverse_proxy_companion_access_log_format_presets"
169: 
170: - name: Fail when mixing generic workers with new specialized workers
171:   ansible.builtin.fail:
172:     msg: >-
173:       Generic workers should not be mixed with the new specialized worker types (room workers, sync workers, client readers, and federation readers)
174:   when: matrix_synapse_workers_generic_workers_count | int > 0 and ((matrix_synapse_workers_room_workers_count | int + matrix_synapse_workers_sync_workers_count | int + matrix_synapse_workers_client_reader_workers_count | int + matrix_synapse_workers_federation_reader_workers_count | int) > 0)
175: 
176: - when: matrix_synapse_container_image_customizations_templates_enabled | bool
177:   block:
178:     - name: Fail if required `matrix_synapse_container_image_customizations_templates_*` settings not defined
179:       ansible.builtin.fail:
180:         msg: >-
181:           You need to define a required configuration setting (`{{ item }}`) when enabling `matrix_synapse_container_image_customizations_templates_enabled`.
182:       when: "lookup('vars', item, default='') == ''"
183:       with_items:
184:         - matrix_synapse_container_image_customizations_templates_git_repository_url
185:         - matrix_synapse_container_image_customizations_templates_git_repository_branch
186: 
187:     - name: Fail if required `matrix_synapse_container_image_customizations_templates_git_repository_keyscan_*` settings not defined
188:       ansible.builtin.fail:
189:         msg: >-
190:           You need to define a required configuration setting (`{{ item }}`) when enabling `matrix_synapse_container_image_customizations_templates_git_repository_keyscan`.
191:       when: "matrix_synapse_container_image_customizations_templates_git_repository_keyscan_enabled | bool and lookup('vars', item, default='') == ''"
192:       with_items:
193:         - matrix_synapse_container_image_customizations_templates_git_repository_keyscan_hostname
194: 
195: - name: Fail if known Synapse password provider modules are enabled when auth is delegated to Matrix Authentication Service
196:   ansible.builtin.fail:
197:     msg: "When Synapse is delegating authentication to Matrix Authentication Service (`matrix_synapse_matrix_authentication_service_enabled: true`), it does not make sense to enable password provider modules, because it is not Synapse that is handling authentication. Please disable {{ item }} before enabling Matrix Authentication Service integration for Synapse. Synapse will refuse to start otherwise."
198:   when: matrix_synapse_matrix_authentication_service_enabled and lookup('vars', item, default='') | bool
199:   with_items:
200:     - matrix_synapse_ext_password_provider_rest_auth_enabled
201:     - matrix_synapse_ext_password_provider_shared_secret_auth_enabled
202:     - matrix_synapse_ext_password_provider_ldap_enabled
203: 
204: - name: Fail if password config is enabled for Synapse when auth is delegated to Matrix Authentication Service
205:   ansible.builtin.fail:
206:     msg: "When Synapse is delegating authentication to Matrix Authentication Service (`matrix_synapse_matrix_authentication_service_enabled: true`), it doesn't make sense to enable the password config (`matrix_synapse_password_config_enabled: true`), because it is not Synapse that is handling authentication. Please remove your `matrix_synapse_password_config_enabled: true` setting before enabling Matrix Authentication Service integration for Synapse. Synapse will refuse to start otherwise."
207:   when: matrix_synapse_matrix_authentication_service_enabled and matrix_synapse_password_config_enabled
208: 
209: - name: Fail if registration is enabled for Synapse when auth is delegated to Matrix Authentication Service
210:   ansible.builtin.fail:
211:     msg: "When Synapse is delegating authentication to Matrix Authentication Service (`matrix_synapse_matrix_authentication_service_enabled: true`), it doesn't make sense to enable registration (`matrix_synapse_enable_registration: true`), because it is not Synapse that is handling authentication. Synapse will refuse to start otherwise."
212:   when: matrix_synapse_matrix_authentication_service_enabled and matrix_synapse_enable_registration
213: 
214: - name: Fail if registration CAPTCHA is enabled for Synapse when auth is delegated to Matrix Authentication Service
215:   ansible.builtin.fail:
216:     msg: "When Synapse is delegating authentication to Matrix Authentication Service (`matrix_synapse_matrix_authentication_service_enabled: true`), it doesn't make sense to enable registration CAPTCHA (`matrix_synapse_enable_registration_captcha: true`), because it is not Synapse that is handling authentication. Synapse will refuse to start otherwise."
217:   when: matrix_synapse_matrix_authentication_service_enabled and matrix_synapse_enable_registration_captcha
218: 
219: - name: Fail if OpenID Connect is enabled for Synapse when auth is delegated to Matrix Authentication Service
220:   ansible.builtin.fail:
221:     msg: "When Synapse is delegating authentication to Matrix Authentication Service (`matrix_synapse_matrix_authentication_service_enabled: true`), it doesn't make sense to enable OpenID Connect (`matrix_synapse_oidc_enabled: true`), because it is not Synapse that is handling authentication. Synapse will refuse to start otherwise."
222:   when: matrix_synapse_matrix_authentication_service_enabled and matrix_synapse_oidc_enabled and not matrix_authentication_service_migration_in_progress
223: 
224: - name: Fail if CAS config is enabled for Synapse when auth is delegated to Matrix Authentication Service
225:   ansible.builtin.fail:
226:     msg: "When Synapse is delegating authentication to Matrix Authentication Service (`matrix_synapse_matrix_authentication_service_enabled: true`), it doesn't make sense to enable CAS config (`matrix_synapse_cas_config_enabled: true`), because it is not Synapse that is handling authentication. Synapse will refuse to start otherwise."
227:   when: matrix_synapse_matrix_authentication_service_enabled and matrix_synapse_cas_config_enabled
228: 
229: - name: Fail if QR code login (MSC4108) is enabled while Matrix Authentication Service is not
230:   ansible.builtin.fail:
231:     msg: "When Synapse QR code login is enabled (MSC4108 via `matrix_synapse_experimental_features_msc4108_enabled`), Matrix Authentication Service integration (`matrix_synapse_matrix_authentication_service_enabled`) must also be enabled."
232:   when: matrix_synapse_experimental_features_msc4108_enabled and not matrix_synapse_matrix_authentication_service_enabled

  1: - hosts: ringnode
  2:   tasks:
  3:     - include_vars: "vault/ringnode.yml"
  4:   tags:
  5:     - always
  6: 
  7: - hosts: infranode
  8:   tasks:
  9:     - include_vars: "{{ item }}"
 10:       with_first_found:
 11:         - "vault/{{ inventory_hostname}}.yml"
 12:         - "vault/infranode.yml"
 13:   tags:
 14:     - always
 15: 
 16: - import_playbook: ubuntu_upgrade.yml
 17:   when: '"ringnode" in group_names and ansible_distribution_release != "jammy"'
 18: 
 19: - hosts: all
 20:   become: true
 21:   become_user: root
 22:   roles:
 23:     - { role: apt, tags: apt }
 24:     - { role: resolving, tags: resolving }
 25:     - { role: etcfiles, tags: etcfiles }
 26:     - { role: syslog, tags: syslog }
 27:     - { role: sysctl, tags: sysctl }
 28:     - { role: lang, tags: lang }
 29:     - { role: ansible, tags: ansible }
 30:     - { role: software, tags: software }
 31:     - { role: ntp, tags: ntp }
 32:     - { role: motd, tags: motd }
 33:     - { role: munin-node, tags: munin-node }
 34:     - { role: dhcp, tags: dhcp }
 35:     - { role: fail2ban, tags: fail2ban }
 36:     - { role: postfix, tags: postfix }
 37:     - { role: userscripts, tags: userscripts }
 38:     - { role: adminscripts, tags: adminscripts }
 39:     - { role: users, class: ring-admins, tags: ring-admins }
 40:     - { role: users, class: local, tags: local-users }
 41:     - { role: openssh, tags: openssh }
 42: 
 43: - hosts: ringnode:auth.infra.ring.nlnog.net
 44:   become: true
 45:   become_user: root
 46:   roles:
 47:     - { role: users, class: ring-users, tags: ring-users }
 48: 
 49: - hosts: ringnode:~staging[0-9]*\.ring\.nlnog\.net
 50:   become: true
